    var bb='[align=center][size=14][color='+rank.color+'][b]'+composedTitle()+'[/b][/color][/size][/align]\n[hr]\n[quote][table layout=fixed width=100%]\n[tr]\n[td]'+img1+'\n[/td]\n[td]\n[align=center][b]\u0412\u0438\u0434:[/b] [i]'+typeLabel()+'[/i]\n[b]\u0420\u0430\u043d\u0433:[/b] [i]'+value('rank')+'[/i]\n'+natureBlock+'[b]\u041a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u0447\u0430\u043a\u0440\u044b:[/b] [i]'+chakraText+'[/i]'+maintenanceLine+'\n[b]\u0422\u0438\u043f \u044d\u0444\u0444\u0435\u043a\u0442\u0430:[/b] [i]'+value('effectText')+(value('effectExtra')?' \u2014 '+value('effectExtra'):'')+'[/i]\n'+effectLine+'[b]\u0414\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u043f\u0440\u0438\u043c\u0435\u043d\u0435\u043d\u0438\u044f:[/b] [i]'+distanceText()+'[/i][/align][/td]\n[td][align=right]'+img2+'\n[/align][/td]\n[/tr]\n[/table]\n[hr]\n[td][b]\u041e\u043f\u0438\u0441\u0430\u043d\u0438\u0435:[/b] [i]'+descriptionText+'[/i][/td]\n[hr]\n[table layout=fixed width=100%]\n[tr]\n[td][b][color=red]\u041f\u0440\u0438\u043c\u0435\u0447\u0430\u043d\u0438\u0435:[/color][/b]\n'+notes().map(bullet).join('\n')+'\n[/td]\n[/tr]\n[/table][b]\u041f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u0438:[/b] [i][color=navy]'+(value('users')||'\u043d\u0435 \u0443\u043a\u0430\u0437\u0430\u043d\u044b')+'[/color][/i][/quote]\n[hr]\n[b]\u041a\u043e\u0434 \u0434\u043b\u044f \u0432\u0441\u0442\u0430\u0432\u043a\u0438 \u0432 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b[/b]\n[code]'+parameterLink+'[/code]\n[color=green][align=right][i]By '+(value('author')||'\u043d\u0438\u043a \u0441\u043e\u0437\u0434\u0430\u0442\u0435\u043b\u044f \u0442\u0435\u0445\u043d\u0438\u043a\u0438')+'[/i][/align][/color]\n[hr]';
