    var title=v('title')||'\u041d\u0430\u0437\u0432\u0430\u043d\u0438\u0435 \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u0430',fullTitle=q('latin').checked&&v('latinTitle')?title+' / '+v('latinTitle'):title,color=colors[v('rank')],damage=increase(v('damage'),allowed?n('extraDamage'):0),critical=increase(v('critical'),allowed?n('extraCritical'):0),chance=Math.min(100,n('chance')+(allowed?n('extraChance'):0));
