    var lines=[line('\u0420\u0430\u043d\u0433 \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u0430',v('rank')),line('\u0411\u0430\u0437\u043e\u0432\u044b\u0439 \u0442\u0438\u043f',v('base')||(weapon?'\u041e\u0440\u0443\u0436\u0438\u0435':'\u041f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0430'))];if(weapon)lines.push(line('\u0422\u0438\u043f \u0443\u0440\u043e\u043d\u0430',v('damageType')));lines.push(line('\u0412\u0430\u0440\u0438\u0430\u043d\u0442\u044b \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u044f',v('usage')),line('\u0420\u0430\u0437\u043c\u0435\u0440',v('size')));if(weapon)lines.push(line('\u0423\u0440\u043e\u043d',damage),line('\u041a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0443\u0440\u043e\u043d',critical+(critical&&critical!=='-'&&critical!=='\u2014'?' (\u0432\u0435\u0440\u043e\u044f\u0442\u043d\u043e\u0441\u0442\u044c '+chance+'%)':'')));lines.push(line('\u041c\u0430\u0442\u0435\u0440\u0438\u0430\u043b',v('material')));
