    var parameterLink='[url='+(v('postUrl')||'\u0441\u0441\u044b\u043b\u043a\u0430 \u043d\u0430 \u043f\u043e\u0441\u0442 \u0441 \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u043e\u043c')+'][color='+color+']'+title.replace(/\[\/?widepost\]/gi,'')+'[/color][/url]';var parameterCode='\n[b]\u041a\u043e\u0434 \u0434\u043b\u044f \u0432\u0441\u0442\u0430\u0432\u043a\u0438 \u0432 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b[/b]\n[code]'+parameterLink+'[/code]\n';
