  function updateCatalog(){app.querySelector('datalist').innerHTML=catalog.map(function(w){return '<option value="'+esc(w.name)+'">'+esc(w.group+' \u00b7 '+w.rank)+'</option>';}).join('');}
  function applyWeapon(){if(v('kind')!=='weapon'){render();return;}var item=catalog.find(function(w){return w.name.toLowerCase()===v('base').toLowerCase();});if(!item){selected=null;render();return;}selected=item;q('damageType').value=item.type;q('damage').value=item.damage;var m=item.critical.match(/\((?:[^)]*?)(\d+(?:[.,]\d+)?)\s*%[^)]*\)/i);q('critical').value=item.critical.replace(/\s*\([^)]*%[^)]*\)/g,'').trim();q('chance').value=m?Number(m[1].replace(',','.')):0;q('requirements').value=item.requirements;q('notes').value=item.bonus&&!/^[-\u2014\u2013]$/.test(item.bonus)?item.bonus:'';['extraDamage','extraCritical','extraChance'].forEach(function(k){q(k).value=0;});render();}
  function parseCatalog(html){var doc=new DOMParser().parseFromString(html,'text/html'),items=[];Array.prototype.forEach.call(doc.querySelectorAll('.spoiler-box'),function(box){var heading=box.firstElementChild;if(!heading)return;var group=heading.textContent.trim();if(group!=='\u0421\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u043e\u0435 \u0432\u043e\u043e\u0440\u0443\u0436\u0435\u043d\u0438\u0435'&&group!=='\u0414\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u043e\u0440\u0443\u0436\u0438\u0435')return;var table=box.querySelector('table');if(!table)return;var rows=table.rows;if(!rows.length)return;function cells(row){return Array.prototype.map.call(row.cells,function(cell){return cell.textContent.replace(/\s+/g,' ').trim();});}var headers=cells(rows[0]).map(function(x){return x.toLowerCase();});function index(label){return headers.indexOf(label.toLowerCase());}var keys={type:'\u0422\u0438\u043f',rank:'\u0420\u0430\u043d\u0433',name:'\u041d\u0430\u0437\u0432\u0430\u043d\u0438\u0435',damage:'\u0423\u0440\u043e\u043d',critical:'\u041a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0443\u0440\u043e\u043d',bonus:'\u0411\u043e\u043d\u0443\u0441\u044b',requirements:'\u0422\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u044f'};if(Object.keys(keys).some(function(k){return index(keys[k])<0;}))return;Array.prototype.forEach.call(rows,function(row,i){if(!i)return;var c=cells(row),item={group:group};Object.keys(keys).forEach(function(k){item[k]=c[index(keys[k])]||'';});if(/^[EDCBAS]$/.test(item.rank)&&item.name)items.push(item);});});return items;}
  var loaded=false;launch.onclick=function(){app.hidden=false;launch.hidden=true;if(!loaded){loaded=true;fetch('/viewtopic.php?id=82',{credentials:'same-origin'}).then(function(r){if(!r.ok)throw new Error();return r.arrayBuffer();}).then(function(buffer){var items=parseCatalog(new TextDecoder('windows-1251').decode(buffer));if(!items.length)throw new Error();catalog=items;updateCatalog();app.querySelector('.aab-status').textContent='\u041a\u0430\u0442\u0430\u043b\u043e\u0433 \u043e\u0431\u043d\u043e\u0432\u043b\u0451\u043d \u0438\u0437 \u0442\u0435\u043c\u044b \u211682: '+items.length+' \u0432\u0438\u0434\u043e\u0432 \u043e\u0440\u0443\u0436\u0438\u044f.';}).catch(function(){app.querySelector('.aab-status').textContent='\u0418\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u0439 \u043a\u0430\u0442\u0430\u043b\u043e\u0433. \u0412\u0441\u0435 \u043f\u043e\u043b\u044f \u043c\u043e\u0436\u043d\u043e \u0440\u0435\u0434\u0430\u043a\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432\u0440\u0443\u0447\u043d\u0443\u044e.';});}app.scrollIntoView({behavior:'smooth',block:'start'});};app.querySelector('.atb-close').onclick=function(){app.hidden=true;launch.hidden=false;};
